void put(Bytes& b,size_t at,uint64_t n,size_t width=8){for(size_t i=0;i<width;++i)b[at+i]=uint8_t(n>>(8*i));}
SignedConsensusBeaconHeader header(const Bytes& b,size_t at){check(at+208<=b.size(),"header size");SignedConsensusBeaconHeader h;h.message={little(b,at,8),little(b,at+8,8),root_at(b,at+16),root_at(b,at+48),root_at(b,at+80)};h.signature=Bytes(b.begin()+at+112,b.begin()+at+208);return h;}
// Test-only registry reader: the fixed common prefix is identical. Remove the
// Altair fixed extension and relocate the six offsets consumed by decode(); no
// pending-attestation parsing or state hashing occurs in this projection.
ConsensusSlashingState registry(const Bytes& b){auto copy=b;const auto extra=little(b,4272,4)-7057;check(extra==3172,"minimal Altair fixed extension");copy.erase(copy.begin()+7057,copy.begin()+7057+extra);for(size_t at:{4272,4348,4360,4364,6928,6932})put(copy,at,little(b,at,4)-extra,4);return decode(copy);}
